const DEMO_PSW_SUR=['土屋','永井','西川','野口','原田','平野'];
// 予定の服装（文字）と、見本の服装写真の色（上・下）。写真は外部から取らず、その場で絵を描いて作る（顔は描かない）
const DEMO_CLOTHES=[['紺のジャケット、ベージュのズボン','#24345e','#cbb48c'],['赤いセーター、黒いズボン','#b8322f','#2b2b2b'],['緑のパーカー、ジーンズ','#3d7a4a','#3b5a8a'],['灰色のコート、紺のズボン','#8a8f96','#25304d'],
  ['白いシャツ、茶色のズボン','#f1f1ec','#7a5532'],['黄色のカーディガン、灰色のスカート','#e2b73c','#8d8f94'],['水色のダウン、黒いズボン','#8cc3e6','#262626'],['えんじ色のトレーナー、灰色のズボン','#7d2735','#7f8288']];
function demoClothesBlob(top,bot){return new Promise(res=>{const c=document.createElement('canvas');c.width=240;c.height=320;const x=c.getContext('2d');
  const g=x.createLinearGradient(0,0,0,320);g.addColorStop(0,'#eef1f5');g.addColorStop(1,'#cdd5df');x.fillStyle=g;x.fillRect(0,0,240,320);
  const rr=(X,Y,W,H,R,col)=>{x.fillStyle=col;x.beginPath();if(x.roundRect)x.roundRect(X,Y,W,H,R);else x.rect(X,Y,W,H);x.fill();x.strokeStyle='rgba(0,0,0,.18)';x.lineWidth=1.5;x.stroke();};
  rr(106,0,28,22,6,'#e4c4a2');                                   // 首（顔は描かない）
  rr(70,154,48,140,10,bot);rr(122,154,48,140,10,bot);             // ズボン
  x.fillStyle='#2a2a2a';x.beginPath();x.ellipse(92,300,30,11,0,0,Math.PI*2);x.ellipse(148,300,30,11,0,0,Math.PI*2);x.fill();   // 靴
  rr(36,26,30,138,15,top);rr(174,26,30,138,15,top);               // 腕
  x.fillStyle='#e4c4a2';x.beginPath();x.arc(51,170,11,0,Math.PI*2);x.arc(189,170,11,0,Math.PI*2);x.fill();
  rr(62,14,116,152,24,top);                                       // 胴
  x.fillStyle='rgba(255,255,255,.85)';x.fillRect(178,6,54,24);x.fillStyle='#14233a';x.font='bold 15px sans-serif';x.fillText('見本',189,24);
  c.toBlob(b=>res(b),'image/jpeg',0.8);});}
// 予定：今日〜30日後に18件（＋もとからの1件）。平日は外出、週末（金・土・日）は外泊を多めに。出発予定を過ぎた予定は作らない
async function demoPlans(list,{now,stf,famOf}){const M=60000,H=3600000,D=86400000;
  const day0=tkDayStart(now);const at=(d,hm)=>tkAtHM(tkAddDays(day0,d),hm);
  const OFF=[0,1,2,3,4,6,7,8,10,12,13,15,17,19,21,24,27,30];
  const RELS=['母','','妻','施設職員','父','','娘','兄','','夫','姉','息子','','弟','妹','その他の親族','','母'];
  const NOPH=[1,5,8,12,16];          // 服装写真なし（出発の時に撮る）
  const RSV=[0,2,4];                 // タグを予約済み（近いうちの予定）
  const OUT_DEST=['自宅','他院受診（内科）','実家','近くのコンビニ','他院受診（歯科）','〇〇駅周辺で買い物','病院周辺の散歩','他院受診（整形外科）','図書館','自宅','他院受診（眼科）'];
  const STAY_DEST=['自宅','実家','自宅','姉の家','実家'];
  const OTHER_SUR=['三宅','宮本','村上','中川','横山','大塚'],GF=['春香','美和','典子','千秋','礼子','静香'],GM=['孝','昭','進','武','実','豊'];
  const fits=(rel,p)=>{const a=+p.age||0,m=p.sex==='男';return rel==='妻'?m&&a>=30:rel==='夫'?!m&&a>=30:(rel==='息子'||rel==='娘')?a>=55:(rel==='母'||rel==='父')?a<60:true;};
  const used=new Set(),pool=list.slice(14,50);let io=0,is=0,n=0;
  for(let i=0;i<OFF.length;i++){
    const rel=RELS[i];const p=pool.find(x=>!used.has(x)&&(!rel||fits(rel,x)))||pool.find(x=>!used.has(x));used.add(p);
    let d=OFF[i];if(d===0&&now+120*M>at(0,'15:00'))d=29;     // 今日はもう遅い時は、29日後に回す
    const wd=new Date(tkAddDays(day0,d)).getDay();
    const kind=(wd===5||wd===6||wd===0)&&i%4!==3?'外泊':'外出';
    let dep,due,dest;
    if(kind==='外出'){dest=OUT_DEST[io++%OUT_DEST.length];const hosp=dest.startsWith('他院受診');dep=at(d,hosp?(i%2?'13:30':'09:00'):['09:30','10:00','13:00','13:30','14:00'][i%5]);due=dep+(hosp?3:[2,3,4,5][i%4])*H;}
    else{dest=STAY_DEST[is++%STAY_DEST.length];dep=at(d,['10:00','13:00','14:00'][i%3]);due=at(d+(wd===5?2:1),['15:00','16:00','17:00'][i%3]);}
    if(d===0&&dep<now+120*M){const t=Math.ceil((now+120*M)/(30*M))*30*M;due=t+(due-dep);dep=t;}
    let comp=null;
    if(rel){const sur=p.name.replace('(デモ) ','').split(' ')[0];const fem=['母','妻','姉','妹','娘','その他の親族'].includes(rel)||(rel==='施設職員'&&i%2);
      const own=['母','父','妻','夫','兄','弟','息子'].includes(rel)||(['姉','妹','娘'].includes(rel)&&i%2===0);
      comp={name:`${own?sur:OTHER_SUR[Math.floor(i/3)%OTHER_SUR.length]} ${(fem?GF:GM)[i%6]}`,tel:'090-0000-'+(3001+i)};}
    const ph=!NOPH.includes(i);const cl=DEMO_CLOTHES[i%DEMO_CLOTHES.length];
    const o={id:uid(),name:p.name,pid:p.pid,kana:p.kana,sex:p.sex,age:p.age,ward:p.ward,adm:p.adm,kind,departAt:dep,dueAt:due,dueAtOriginal:due,dest,alone:!comp,
      compName:comp?comp.name:'',compRel:comp?rel:'',compTel:comp?comp.tel:'',...famOf(p),clothes:ph||i%2?cl[0]:'',note:'',tagId:'',consent:false,departNurse:stf(),status:'planned',createdAt:now,hasPhoto:ph,demo:true,log:[]};
    if(RSV.includes(i)){const tid='T-'+pad(10+RSV.indexOf(i));if(await addTag(tid)){const nt=tags.find(x=>x.id===tid);nt.demo=true;await saveTag(nt);}
      const t=tags.find(x=>x.id===tid&&x.status==='available');
      if(t){if(!p.consentDate){p.consentDate=toDateInput(now-30*D);p.consentLog=[...(p.consentLog||[]),{at:now-30*D,text:'同意書取得日を '+ymd(p.consentDate)+' に登録',by:stf()}];}
        o.tagId=t.id;o.consent=true;o.consentDate=p.consentDate;t.status='reserved';t.outingId=o.id;await saveTag(t);}}
    addLog(o,`${kind}の予定を登録（出発予定 ${fmt(dep)}）`+(o.tagId?`（タグ ${o.tagId} を予約）`:''),o.departNurse);if(ph)addLog(o,'服装写真を登録',o.departNurse);
    o.patientId=(await upsertPatient(o,null)).id;await saveOuting(o);if(ph)await dbPut('photos',await demoClothesBlob(cl[1],cl[2]),o.id);outings.push(o);n++;}
  return n;}
// 帰院済みの記録：過去10日に10件（遅れ2件・外泊1件・タグあり5件）。出発確認・帰院確認の職員も架空の30人から
async function demoHistory(list,{now,stf}){const M=60000,H=3600000,D=86400000;const day0=tkDayStart(now);const at=(d,hm)=>tkAtHM(tkAddDays(day0,d),hm);
  const DEST=['自宅','病院周辺の散歩','近くのコンビニ','〇〇駅周辺で買い物','実家','図書館','他院受診（内科）','自宅','喫煙','病院周辺の散歩'];let n=0;
  for(let k=4;k<=13;k++){const p=list[k];const dd=k-3;const kind=k===9?'外泊':'外出';
    const dep=at(-dd,['10:00','13:00','13:30','09:30'][k%4]);const due=kind==='外泊'?at(-dd+1,'16:00'):dep+[2,3,4][k%3]*H;
    const late=k===6?25*M:k===11?50*M:-[10,20,5][k%3]*M;const ret=Math.min(due+late,now-H);
    const tag=k%2===0?(k%4===0?'T-04':'T-05'):'';const comp=k%3!==0;const dn=stf(),rn=stf();
    if(tag&&!p.consentDate){p.consentDate=toDateInput(dep-20*D);p.consentLog=[...(p.consentLog||[]),{at:dep-20*D,text:'同意書取得日を '+ymd(p.consentDate)+' に登録',by:stf()}];}
    const o={id:uid(),name:p.name,pid:p.pid,kana:p.kana,sex:p.sex,age:p.age,ward:p.ward,adm:p.adm,kind,departAt:dep,dueAt:due,dueAtOriginal:due,dest:DEST[k-4],alone:!comp,
      compName:comp?p.famName:'',compRel:comp?p.famRel:'',compTel:comp?p.famTel:'',famName:p.famName,famRel:p.famRel,famTel:p.famTel,selfTel:p.selfTel,clothes:DEMO_CLOTHES[k%DEMO_CLOTHES.length][0],note:'',
      tagId:tag,consent:!!tag,consentDate:tag?p.consentDate:'',departNurse:dn,status:'returned',returnedAt:ret,returnNurse:rn,tagReturned:!!tag,rc:{other:''},createdAt:dep,hasPhoto:false,demo:true,patientId:p.id,
      log:[{at:dep,text:`${kind}に出発`+(tag?`（タグ ${tag} 貸出）`:'（タグなし）'),by:dn}]};
    if(k%3===0)o.log.push({at:dep,text:'服装写真を登録',by:dn});
    if(ret>due)o.log.push({at:due,text:'帰院予定時刻を超過（アラーム）',by:''});
    o.log.push({at:ret,text:'帰院',by:rn});if(tag)o.log.push({at:ret,text:`タグ ${tag} 回収`,by:rn});
    if(k%3===0){o.photoDeletedAt=ret;o.log.push({at:ret,text:'服装写真を削除（自動）',by:''});}
    Object.assign(p,{lastOutAt:dep,lastDest:o.dest,dests:[o.dest],count:Math.max(1,p.count||0),lastComp:{alone:o.alone,compName:o.compName,compRel:o.compRel,compTel:o.compTel}});
    await saveOuting(o);outings.push(o);n++;}
  return n;}
