  const GMo=[['健一','けんいち'],['正夫','まさお'],['茂','しげる'],['博','ひろし'],['清','きよし'],['和夫','かずお']],GFo=[['和子','かずこ'],['節子','せつこ'],['洋子','ようこ'],['弘子','ひろこ'],['久美子','くみこ']];
