      adm:rnd()<0.7?'任意入院':'医療保護入院',selfTel:rnd()<0.4?`090-0000-${2000+k}`:'',famName:`${famSur} ${fam[0]}`,famRel:rel,famTel:`090-0000-${1000+k}`,
